import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';
import { CommandeService } from 'src/app/services/commande.service';

@Component({
  selector: 'app-medicament-list',
  templateUrl: './medicament-list.component.html',
  styleUrls: ['./medicament-list.component.css']
})
export class MedicamentListComponent implements OnInit {
  medicaments: Medicament[] = []; // Ensure it is never null
  fournisseurId: number = 0;
  selectedMedicaments: { medicamentId: number, quantite: number }[] = [];

  constructor(
    private fournisseurService: FournisseurService,
    private route: ActivatedRoute,
    private commandeService: CommandeService
  ) { }

  ngOnInit(): void {
    const idParam = this.route.snapshot.paramMap.get('id');
    this.fournisseurId = idParam ? +idParam : 0;

    if (this.fournisseurId) {
      this.getMedicamentsByFournisseur(this.fournisseurId);
    } else {
      console.error("Invalid Fournisseur ID");
    }
  }

  // Fetch medications from the API
  getMedicamentsByFournisseur(idFournisseur: number): void {
    this.fournisseurService.getMedicamentsByFournisseur(idFournisseur).subscribe(
      data => {
        console.log("API Response:", data); 
        this.medicaments = data ?? [];  // Ensure it's an array, not null
      },
      error => {
        console.error("Error fetching medicaments", error);
        this.medicaments = [];  // Fallback to an empty list
      }
    );
  }


  // Update selected medications and quantities
  updateSelection(medicamentId: number | undefined, quantite: string): void {
    if (!medicamentId) {
      console.warn("Invalid Medicament ID");
      return;
    }

    const quantiteNum = parseInt(quantite, 10);
    if (isNaN(quantiteNum) || quantiteNum <= 0) {
      console.warn("Invalid quantity:", quantite);
      return;
    }

    const existing = this.selectedMedicaments.find(item => item.medicamentId === medicamentId);
    if (existing) {
      existing.quantite = quantiteNum;
    } else {
      this.selectedMedicaments.push({ medicamentId, quantite: quantiteNum });
    }
  }


  // Place the order
  passerCommande(): void {
    if (this.selectedMedicaments.length === 0) {
      console.warn("No medications selected for ordering.");
      return;
    }

    const commande = {
      fournisseurId: this.fournisseurId,
      status: 'Encours',
      medicaments: this.selectedMedicaments
    };

    this.commandeService.passerCommande(commande).subscribe(
      response => {
        console.log('Commande passée avec succès', response);
        alert("Commande passée avec succès !");
        this.selectedMedicaments = []; // Reset selection after successful order
      },
      error => {
        console.error('Erreur lors de la commande', error);
      }
    );
  }
}
